def parse_duration(s: str) -> int:
    import re

    # Define patterns for hours, minutes and seconds
    patterns = {
        r'(\d+)h': lambda m: int(m.group(1)) * 3600,
        r'(\d+)m': lambda m: int(m.group(1)) * 60,
        r'(\d+)s': lambda m: int(m.group(1)),
    }

    # Find all matches
    matches = [m for m in re.finditer('|'.join(patterns.keys()), s)]

    # Calculate total duration
    total_seconds = 0
    for match in matches:
        for pattern, func in patterns.items():
            if pattern in match.group():
                total_seconds += func(match)

    return total_seconds
```

